  case OP_NEG:if(!sp||st[sp-1].n==INT64_MIN){rc=4;goto done;}st[sp-1].n=-st[sp-1].n;break;
  case OP_DUP:if(!sp||sp==4096){rc=3;goto done;}st[sp]=st[sp-1];sp++;break;case OP_DROP:if(!sp){rc=3;goto done;}sp--;break;case OP_SWAP:if(sp<2){rc=3;goto done;}a=st[sp-1];st[sp-1]=st[sp-2];st[sp-2]=a;break;
