  case OP_PRINT:if(!sp){rc=3;goto done;}sprint(stdout,st[sp-1]);fputc('\n',stdout);break;
  case OP_EMIT:if(!sp){rc=3;goto done;}a=st[--sp];if(a.e||a.n<0||a.n>255){rc=4;goto done;}fputc((int)a.n,stdout);break;
