  case OP_CALL:if(cp==1024||x->a<0||(uint64_t)x->a>=n){rc=3;goto done;}calls[cp++]=ip+1;next=(uint64_t)x->a;break;case OP_RET:if(!cp){rc=3;goto done;}next=calls[--cp];break;
  case OP_LOADV:if(x->a<0||x->a>=256||sp==4096){rc=3;goto done;}st[sp++]=vars[x->a];break;case OP_STOREV:if(x->a<0||x->a>=256||!sp){rc=3;goto done;}vars[x->a]=st[--sp];break;
