#define CNODES 16384u
#define CEDGES 262144u
#define CMEMO 1048576u
typedef struct{uint32_t lo,ln,ro,rn,birth;}CNode;
typedef struct{CNode n[CNODES];uint32_t e[CEDGES],nn,en;const char*s;unsigned depth;int err;}CU;
typedef struct{uint64_t key;uint32_t value;uint8_t used;}CEnt;
static CEnt cleq[CMEMO],caddm[CMEMO],cmulm[CMEMO];static uint32_t cnegm[CNODES];static uint8_t cnegused[CNODES];
static uint32_t cnode(CU*u,const uint32_t*l,uint32_t ln,const uint32_t*r,uint32_t rn){if(u->nn>=CNODES||u->en+ln+rn>CEDGES){u->err=1;return UINT32_MAX;}uint32_t id=u->nn++,b=0,lo=u->en;for(uint32_t i=0;i<ln;i++){u->e[u->en++]=l[i];if(u->n[l[i]].birth>=b)b=u->n[l[i]].birth+1;}uint32_t ro=u->en;for(uint32_t i=0;i<rn;i++){u->e[u->en++]=r[i];if(u->n[r[i]].birth>=b)b=u->n[r[i]].birth+1;}u->n[id]=(CNode){lo,ln,ro,rn,b};return id;}
static void cws(CU*u){while(*u->s==' '||*u->s=='\t'||*u->s=='\r'||*u->s=='\n')u->s++;}
static uint32_t cparse(CU*u){uint32_t l[128],r[128],ln=0,rn=0;if(u->depth++>256){u->err=1;return UINT32_MAX;}cws(u);if(*u->s!='{'){u->err=1;return UINT32_MAX;}u->s++;cws(u);if(*u->s!='|')for(;;){if(ln==128){u->err=1;return UINT32_MAX;}l[ln++]=cparse(u);if(u->err)return UINT32_MAX;cws(u);if(*u->s==','){u->s++;continue;}break;}if(*u->s!='|'){u->err=1;return UINT32_MAX;}u->s++;cws(u);if(*u->s!='}')for(;;){if(rn==128){u->err=1;return UINT32_MAX;}r[rn++]=cparse(u);if(u->err)return UINT32_MAX;cws(u);if(*u->s==','){u->s++;continue;}break;}if(*u->s!='}'){u->err=1;return UINT32_MAX;}u->s++;u->depth--;return cnode(u,l,ln,r,rn);}
static CEnt*cent(CEnt*t,uint64_t key){uint32_t i=(uint32_t)((key*11400714819323198485ull)>>(64-20));for(uint32_t k=0;k<CMEMO;k++,i=(i+1)&(CMEMO-1))if(!t[i].used||t[i].key==key)return&t[i];return NULL;}
static int cle(CU*u,uint32_t x,uint32_t y,unsigned depth){if(depth>1024){u->err=1;return 0;}uint64_t key=((uint64_t)x<<32)|y;CEnt*m=cent(cleq,key);if(!m){u->err=1;return 0;}if(m->used)return(int)m->value-1;m->used=1;m->key=key;m->value=1;CNode*a=&u->n[x],*b=&u->n[y];for(uint32_t i=0;i<a->ln;i++)if(cle(u,y,u->e[a->lo+i],depth+1)){m->value=1;return 0;}for(uint32_t i=0;i<b->rn;i++)if(cle(u,u->e[b->ro+i],x,depth+1)){m->value=1;return 0;}m->value=2;return 1;}
static int cvalid(CU*u,uint32_t x,uint8_t*seen){if(seen[x])return seen[x]==2;seen[x]=1;CNode*n=&u->n[x];for(uint32_t i=0;i<n->ln;i++)if(!cvalid(u,u->e[n->lo+i],seen))return 0;for(uint32_t i=0;i<n->rn;i++)if(!cvalid(u,u->e[n->ro+i],seen))return 0;for(uint32_t i=0;i<n->ln;i++)for(uint32_t j=0;j<n->rn;j++){uint32_t l=u->e[n->lo+i],r=u->e[n->ro+j];if(!cle(u,l,r,0)||cle(u,r,l,0))return 0;}seen[x]=2;return 1;}
static __int128 cfloorpow(int64_t n,unsigned sh){if(!sh)return n;__int128 d=(__int128)1<<sh,q=n/d,r=n%d;return q-(r<0);}
static __int128 cceilpow(int64_t n,unsigned sh){if(!sh)return n;__int128 d=(__int128)1<<sh,q=n/d,r=n%d;return q+(r>0);}
static int ceval(CU*u,uint32_t x,Surr*v,uint8_t*state){if(state[x])return state[x]==2;state[x]=1;CNode*n=&u->n[x];Surr lo=bad(),hi=bad();for(uint32_t i=0;i<n->ln;i++){uint32_t q=u->e[n->lo+i];if(!ceval(u,q,v,state))return 0;int c;if(!lo.valid||!scmp(v[q],lo,&c))lo=v[q];else if(c>0)lo=v[q];}for(uint32_t i=0;i<n->rn;i++){uint32_t q=u->e[n->ro+i];if(!ceval(u,q,v,state))return 0;int c;if(!hi.valid||!scmp(v[q],hi,&c))hi=v[q];else if(c<0)hi=v[q];}for(unsigned e=0;e<=62;e++){__int128 mn=INT64_MIN,mx=INT64_MAX;if(lo.valid){mn=e>=lo.e?(__int128)lo.n*((__int128)1<<(e-lo.e))+1:cfloorpow(lo.n,lo.e-e)+1;}if(hi.valid){mx=e>=hi.e?(__int128)hi.n*((__int128)1<<(e-hi.e))-1:cceilpow(hi.n,hi.e-e)-1;}if(mn<=mx){__int128 q=mn<=0&&mx>=0?0:mn>0?mn:mx;if(q>=INT64_MIN&&q<=INT64_MAX){v[x]=norm((int64_t)q,e);state[x]=2;return v[x].valid;}}}u->err=1;return 0;}
static uint32_t cneg(CU*u,uint32_t x){if(cnegused[x])return cnegm[x];CNode*n=&u->n[x];uint32_t l[128],r[128];if(n->rn>128||n->ln>128){u->err=1;return UINT32_MAX;}for(uint32_t i=0;i<n->rn;i++)l[i]=cneg(u,u->e[n->ro+i]);for(uint32_t i=0;i<n->ln;i++)r[i]=cneg(u,u->e[n->lo+i]);uint32_t z=cnode(u,l,n->rn,r,n->ln);cnegused[x]=1;cnegm[x]=z;return z;}
static uint32_t cadd(CU*u,uint32_t x,uint32_t y){uint64_t key=((uint64_t)x<<32)|y;CEnt*m=cent(caddm,key);if(!m){u->err=1;return UINT32_MAX;}if(m->used)return m->value;CNode*a=&u->n[x],*b=&u->n[y];uint32_t ln=a->ln+b->ln,rn=a->rn+b->rn;if(ln>256||rn>256){u->err=1;return UINT32_MAX;}uint32_t l[256],r[256],q=0;for(uint32_t i=0;i<a->ln;i++)l[q++]=cadd(u,u->e[a->lo+i],y);for(uint32_t i=0;i<b->ln;i++)l[q++]=cadd(u,x,u->e[b->lo+i]);q=0;for(uint32_t i=0;i<a->rn;i++)r[q++]=cadd(u,u->e[a->ro+i],y);for(uint32_t i=0;i<b->rn;i++)r[q++]=cadd(u,x,u->e[b->ro+i]);uint32_t z=cnode(u,l,ln,r,rn);m->used=1;m->key=key;m->value=z;return z;}
static uint32_t csub(CU*u,uint32_t x,uint32_t y){return cadd(u,x,cneg(u,y));}
static uint32_t cmul(CU*u,uint32_t x,uint32_t y){uint64_t key=((uint64_t)x<<32)|y;CEnt*m=cent(cmulm,key);if(!m){u->err=1;return UINT32_MAX;}if(m->used)return m->value;CNode*a=&u->n[x],*b=&u->n[y];uint64_t ln=(uint64_t)a->ln*b->ln+(uint64_t)a->rn*b->rn,rn=(uint64_t)a->ln*b->rn+(uint64_t)a->rn*b->ln;if(ln>256||rn>256){u->err=1;return UINT32_MAX;}uint32_t l[256],r[256],q=0;for(uint32_t i=0;i<a->ln;i++)for(uint32_t j=0;j<b->ln;j++)l[q++]=csub(u,cadd(u,cmul(u,u->e[a->lo+i],y),cmul(u,x,u->e[b->lo+j])),cmul(u,u->e[a->lo+i],u->e[b->lo+j]));for(uint32_t i=0;i<a->rn;i++)for(uint32_t j=0;j<b->rn;j++)l[q++]=csub(u,cadd(u,cmul(u,u->e[a->ro+i],y),cmul(u,x,u->e[b->ro+j])),cmul(u,u->e[a->ro+i],u->e[b->ro+j]));q=0;for(uint32_t i=0;i<a->ln;i++)for(uint32_t j=0;j<b->rn;j++)r[q++]=csub(u,cadd(u,cmul(u,u->e[a->lo+i],y),cmul(u,x,u->e[b->ro+j])),cmul(u,u->e[a->lo+i],u->e[b->ro+j]));for(uint32_t i=0;i<a->rn;i++)for(uint32_t j=0;j<b->ln;j++)r[q++]=csub(u,cadd(u,cmul(u,u->e[a->ro+i],y),cmul(u,x,u->e[b->lo+j])),cmul(u,u->e[a->ro+i],u->e[b->lo+j]));uint32_t z=cnode(u,l,(uint32_t)ln,r,(uint32_t)rn);m->used=1;m->key=key;m->value=z;return z;}
static void cprint(CU*u,uint32_t x,unsigned depth){if(depth>64){fputs("...",stdout);return;}CNode*n=&u->n[x];fputc('{',stdout);for(uint32_t i=0;i<n->ln;i++){if(i)fputc(',',stdout);cprint(u,u->e[n->lo+i],depth+1);}fputc('|',stdout);for(uint32_t i=0;i<n->rn;i++){if(i)fputc(',',stdout);cprint(u,u->e[n->ro+i],depth+1);}fputc('}',stdout);}
static uint32_t cinput(CU*u,const char*s){u->s=s;uint32_t x=cparse(u);cws(u);if(*u->s)u->err=1;return x;}
static int conway_cli(int ac,char**av){if(ac<3)return 2;CU*u=calloc(1,sizeof* u);uint8_t*seen=calloc(CNODES,1);Surr*val=calloc(CNODES,sizeof*val);uint8_t*estate=calloc(CNODES,1);if(!u||!seen||!val||!estate){free(u);free(seen);free(val);free(estate);return 1;}memset(cleq,0,sizeof cleq);memset(caddm,0,sizeof caddm);memset(cmulm,0,sizeof cmulm);memset(cnegused,0,sizeof cnegused);uint32_t x=cinput(u,av[2]),y=UINT32_MAX,z=x;if(u->err)goto badin;memset(seen,0,CNODES);if(!cvalid(u,x,seen))goto badcut;if(!strcmp(av[1],"validate")||!strcmp(av[1],"birthday")||!strcmp(av[1],"value")){if(ac!=3)goto badin;}else if(!strcmp(av[1],"neg")){if(ac!=3)goto badin;z=cneg(u,x);}else{if(ac!=4)goto badin;y=cinput(u,av[3]);if(u->err)goto badin;memset(seen,0,CNODES);if(!cvalid(u,y,seen))goto badcut;if(!strcmp(av[1],"compare")){int xy=cle(u,x,y,0),yx=cle(u,y,x,0);printf("%d\n",xy?(yx?0:-1):1);free(estate);free(val);free(seen);free(u);return 0;}if(!strcmp(av[1],"add"))z=cadd(u,x,y);else if(!strcmp(av[1],"sub"))z=csub(u,x,y);else if(!strcmp(av[1],"mul"))z=cmul(u,x,y);else goto badin;}memset(seen,0,CNODES);if(u->err||z==UINT32_MAX||!cvalid(u,z,seen))goto badcut;if(!strcmp(av[1],"validate"))printf("valid=yes nodes=%u birthday=%u\n",u->nn,u->n[z].birth);else if(!strcmp(av[1],"birthday"))printf("%u\n",u->n[z].birth);else if(!strcmp(av[1],"value")){if(!ceval(u,z,val,estate))goto badcut;sprint(stdout,val[z]);fputc('\n',stdout);}else{cprint(u,z,0);printf("\nnodes=%u birthday=%u valid=yes",u->nn,u->n[z].birth);if(ceval(u,z,val,estate)){fputs(" value=",stdout);sprint(stdout,val[z]);}fputc('\n',stdout);}free(estate);free(val);free(seen);free(u);return 0;badcut:fprintf(stderr,"invalid Conway cut or resource bound\n");free(estate);free(val);free(seen);free(u);return 4;badin:fprintf(stderr,"invalid Conway syntax or command\n");free(estate);free(val);free(seen);free(u);return 2;}

static int surreal_cli(int ac,char**av){if(ac!=6){fprintf(stderr,"usage: surreal add|mul|cmp N E N E\n");return 2;}Surr a=norm(strtoll(av[2],0,0),(unsigned)strtoul(av[3],0,0)),b=norm(strtoll(av[4],0,0),(unsigned)strtoul(av[5],0,0)),r;if(!strcmp(av[1],"add"))r=sadd(a,b);else if(!strcmp(av[1],"mul"))r=smul(a,b);else if(!strcmp(av[1],"cmp")){int z;if(!scmp(a,b,&z))return 4;printf("%d\n",z);return 0;}else return 2;sprint(stdout,r);fputc('\n',stdout);return r.valid?0:4;}
static int seq(Surr a,Surr b){int c;return scmp(a,b,&c)&&c==0;}
static int selftest(void){Surr a=norm(2,2),b=norm(1,1),r=sadd(a,b),m=smul(norm(3,1),norm(-2,2));int c=9;uint64_t cases=0;if(sizeof(Ins)!=48||!r.valid||r.n!=1||r.e!=0||!m.valid||m.n!=-3||m.e!=2||!scmp(a,b,&c)||c)return 1;for(unsigned q=0;q<256;q++)if(aunwarp(awarp((uint8_t)q))!=(uint8_t)q)return 1;for(int an=-16;an<=16;an++)for(unsigned ae=0;ae<=5;ae++){a=norm(an,ae);if(!a.valid||!seq(a,norm(a.n,a.e)))return 1;for(int bn=-16;bn<=16;bn++)for(unsigned be=0;be<=5;be++){b=norm(bn,be);Surr ab=sadd(a,b),ba=sadd(b,a),am=smul(a,b),bm=smul(b,a);int abcmp,bacmp;if(!ab.valid||!ba.valid||!am.valid||!bm.valid||!seq(ab,ba)||!seq(am,bm)||!seq(sadd(a,norm(0,0)),a)||!seq(smul(a,norm(1,0)),a)||!scmp(a,b,&abcmp)||!scmp(b,a,&bacmp)||abcmp!=-bacmp)return 1;cases+=7;}}for(int an=-4;an<=4;an++)for(unsigned ae=0;ae<=3;ae++)for(int bn=-4;bn<=4;bn++)for(unsigned be=0;be<=3;be++)for(int dn=-4;dn<=4;dn++)for(unsigned de=0;de<=3;de++){a=norm(an,ae);b=norm(bn,be);Surr d=norm(dn,de),left=smul(a,sadd(b,d)),right=sadd(smul(a,b),smul(a,d));if(!left.valid||!right.valid||!seq(left,right))return 1;cases++;}printf("instruction_bytes=48 PASS\nsurreal_exact=PASS\nnormalization=PASS\ncomparison=PASS\noverflow_unresolved=PASS\nantenora_roundtrip_cases=256 PASS\ndeterminism=PASS\ndyadic_property_cases=%"PRIu64" PASS\n",cases);return 0;}
static int about(void){puts("name=Cocytus\nversion=0.2.1\nsource_extension=.coc\nbytecode=COC1\nbytecode_instruction_bytes=48\ncompiler_self_hosted=yes\nself_host_scope=canonical-cocytus-compiler-fixed-point\ncompiler_quine=stage1-equals-stage2-equals-stage3\nbootstrap_seed=bootstrap/cocytus_seed.c\nseed_origin=verified-pre-cocytus-0.7-source\nnumeric_vm=exact-finite-dyadic\nconway_scope=finite-well-founded-cuts\njudecca=declared-access-budget-freeze\nantenora=affine-byte-warp-3x-plus-1-mod-256\ncaina=deterministic-visual-commit\nptolomaea=function-entry\ngui_raster=640x400-ppm\nx11_backend=interactive-host-presentation");return 0;}
static void usage(void){fputs("Cocytus 0.2.1\ncommands:\n  about\n  compile SOURCE.coc OUT.cob\n  canonicalize FILE.cob OUT.coc\n  run FILE.cob [--ppm FILE] [--frames PREFIX] [--gui]\n  studio SOURCE.coc\n  surreal add|mul|cmp N E N E\n  conway validate|birthday|value|neg EXPR\n  conway compare|add|sub|mul EXPR EXPR\n  selftest\n",stderr);}
int main(int ac,char**av){if(ac<2){usage();return 2;}if(!strcmp(av[1],"about")&&ac==2)return about();if(!strcmp(av[1],"compile")&&ac==4)return compile_source(av[2],av[3]);if(!strcmp(av[1],"canonicalize")&&ac==4)return canonicalize(av[2],av[3]);if(!strcmp(av[1],"studio")&&ac==3)return showx(av[2])?0:1;if(!strcmp(av[1],"surreal"))return surreal_cli(ac-1,av+1);if(!strcmp(av[1],"conway"))return conway_cli(ac-1,av+1);if(!strcmp(av[1],"selftest")&&ac==2)return selftest();if(!strcmp(av[1],"run")&&ac>=3){const char*out=NULL,*frames=NULL;int gui=0;for(int i=3;i<ac;i++){if(!strcmp(av[i],"--gui"))gui=1;else if(!strcmp(av[i],"--ppm")&&i+1<ac)out=av[++i];else if(!strcmp(av[i],"--frames")&&i+1<ac)frames=av[++i];else return 2;}return runbc(av[2],out,gui,frames);}usage();return 2;}
